override dispose(): void {
  if (this._swipeHelper) {
    this._swipeHelper.dispose()
  }

  if (this._resizeObserver) {
    this._resizeObserver.disconnect()
  }

  if (this._resizeFrame !== null) {
    cancelAnimationFrame(this._resizeFrame)
  }

  super.dispose()
}

// Ensure focus moves to the first focusable element when shown
override show(relatedTarget?: HTMLElement): Promise<void> {
  await super.show(relatedTarget)
  const focusable = SelectorEngine.findOne(
    '[autofocus], button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])',
    this._element
  ) ?? this._element
  focusable.focus()
}

